416	  /**
417	   * Time-sliced: sort trees in range into the active list (re-selected every frame) and the static batches: a tree
418	   * that is settled and keeps its level and shadow over every camera position and zoom until the next job (within
419	   * `rebuildDistance` + a margin) needs no per-frame selection.
420	   */
421	  private *rebuild(focus: Vector3, px: number): Generator<void> {
422	    const job = ++this.jobId;
423	    for (const b of this.statics.values()) b.sCount = 0;
424	    this.nextActive.length = 0;
425	    const scatter = this.world.scatter;
426	    const cs = scatter.chunkSize;
427	    const maxD = this.opts.maxDistance;
428	    const shadowD = this.opts.shadowDistance;
429	    const move = (this.opts.rebuildDistance ?? 5) + 4;
430	    const bounds = this.world.map.bounds;
431	    const x0 = Math.floor(Math.max(bounds.minX - 300, focus.x - maxD) / cs);
432	    const x1 = Math.floor(Math.min(bounds.maxX + 300, focus.x + maxD) / cs);
433	    const z0 = Math.floor(Math.max(bounds.minZ - 300, focus.z - maxD) / cs);
434	    const z1 = Math.floor(Math.min(bounds.maxZ + 300, focus.z + maxD) / cs);
435	    for (let cz = z0; cz <= z1; cz++)
436	      for (let cx = x0; cx <= x1; cx++) {
437	        if (Math.hypot((cx + 0.5) * cs - focus.x, (cz + 0.5) * cs - focus.z) - cs * 0.71 > maxD) continue;
438	        for (const inst of scatter.chunk(cx, cz).instances) {
439	          if (!inst.tree) continue;
440	          const st = this.stateOf(inst);
441	          if (!st) continue;
442	          const dx = st.cx - focus.x;
443	          const dy = st.cy - focus.y;
444	          const dz = st.cz - focus.z;
445	          const dist = Math.sqrt(dx * dx + dy * dy + dz * dz);
446	          if (dist > maxD) continue;
447	          const { t, hysteresis: margin } = this.budget(st.lv);
448	          // Neither drawn last frame nor in the last static batches: new, it takes its level at once.
449	          if (st.seen < this.frame - 1 && st.staticJob !== this.committedJob) {
450	            st.from = st.to = selectLevel((st.diameter * px) / Math.max(dist, 0.5), 3, t, 0, dist);
451	            st.fade = 1;
452	            st.dir = 1;
453	          }
454	          st.seen = this.frame;
455	          const dMin = Math.max(dist - move, 0.5);
456	          const dMax = dist + move;
457	          const hMin = (st.diameter * px) / (ZOOM_MARGIN * dMax);
458	          const hMax = (st.diameter * px * ZOOM_MARGIN) / dMin;
459	          const l = st.to;
460	          const steadyLevel =
461	            st.from === l &&
462	            (dMax < FULL_DETAIL_DISTANCE
463	              ? l === 0
464	              : dMin >= FULL_DETAIL_DISTANCE &&
465	                (l === 3 || hMin >= t[l]) &&
466	                (l === 0 || hMax <= t[l - 1] * (1 + margin)));
467	          if (steadyLevel && (dMax < shadowD || dMin >= shadowD)) {
468	            const near = dMax < shadowD;
469	            const sh = near ? shadowLevel(l) : -1;
470	            const angle = Math.atan2(dz, dx);
471	            this.stageStatic(st, l, SOLID, sh === l, near, angle, l);
472	            if (sh >= 0 && sh !== l) this.stageStatic(st, sh, SHADOW_ONLY, true, true, angle, 0);
473	            st.staticJob = job;
474	          } else this.nextActive.push(st);
475	        }
476	        yield;
477	      }
478	    this.focusX = focus.x;
479	    this.focusZ = focus.z;
480	    [this.active, this.nextActive] = [this.nextActive, this.active];
481	    this.committedJob = job;
482	    for (const b of this.statics.values()) {
483	      [b.cMat, b.sMat] = [b.sMat, b.cMat];
484	      [b.cInst, b.sInst] = [b.sInst, b.cInst];
485	      [b.cFade, b.sFade] = [b.sFade, b.cFade];
486	      [b.cAngle, b.sAngle] = [b.sAngle, b.cAngle];
487	      [b.cAlways, b.sAlways] = [b.sAlways, b.cAlways];
488	      b.cCount = b.sCount;
489	      this.packStatic(b);
490	    }
491	    this.packedView = this.view && { ...this.view };
492	    this.commits++;
493	  }
494	
495	  private stageStatic(
496	    st: TreeState,
497	    level: number,
498	    role: number,
499	    shadow: boolean,
500	    always: boolean,
501	    angle: number,
502	    debug: number,
503	  ): void {
504	    const b = this.staticBatch(st.lv, level);
505	    const i = b.sCount++;
506	    b.sMat = grow(b.sMat, (i + 1) * 16);
507	    b.sInst = grow(b.sInst, (i + 1) * 4);
508	    b.sFade = grow(b.sFade, (i + 1) * 4);
509	    b.sAngle = grow(b.sAngle, i + 1);
510	    b.sAlways = grow(b.sAlways, i + 1);
511	    b.sMat.set(st.m, i * 16);
512	    b.sInst.set(st.inst, i * 4);
513	    b.sFade.set([1, role, shadow ? 1 : 0, debug], i * 4);
514	    b.sAngle[i] = angle;
515	    b.sAlways[i] = always ? 1 : 0;
516	  }
517	
518	  /** Every frame: select, fade and write every active tree into the dynamic batches. */
519	  private drawActive(px: number, dt: number): void {
520	    this.frame++;
521	    for (const b of this.dynamic.values()) b.count = 0;
522	    const v = this.view;
523	    const shadowD = this.opts.shadowDistance;
524	    const sx = this.steadyPos.x;
525	    const sy = this.steadyPos.y;
526	    const sz = this.steadyPos.z;
527	    let drawn = 0;
528	    let flickering = 0;
529	    for (const st of this.active) {
530	      const dx = st.cx - sx;
531	      const dy = st.cy - sy;
532	      const dz = st.cz - sz;
533	      const dist = Math.max(Math.sqrt(dx * dx + dy * dy + dz * dz), 0.5);
534	      const near = dist < shadowD;
535	      let visible = near;
536	      if (!visible && v) {
537	        let a = Math.abs(Math.atan2(st.cz - this.focusZ, st.cx - this.focusX) - v.yaw) % (2 * Math.PI);
538	        if (a > Math.PI) a = 2 * Math.PI - a;
539	        visible = a <= v.half;
540	      } else if (!v) visible = true;
541	      const lod = this.budget(st.lv);
542	      const h = (st.diameter * px) / dist;
543	      const sel = selectLevel(h, fadeTarget(st), lod.t, lod.hysteresis, dist);
544	      const fresh = st.seen < this.frame - 1;
545	      st.seen = this.frame;
546	      // Culled (keeps its state) or coming into view: its selected level at once, no fade.
547	      const snap = !visible || !st.visible || fresh || dt === 0;
548	      if (stepFade(st, sel, snap, dt, lod.fadeTime)) this.changed(st);
549	      st.visible = visible;
550	      while (st.changes.length && st.changes[0] < this.time - 1) st.changes.shift();
551	      const flicker = st.changes.length > 2;
552	      if (flicker) flickering++;
553	      // Shadow: one level coarser than the level the tree is settled on (`from` until a fade ends).
554	      const sh = near ? shadowLevel(st.from) : -1;
555	      const debug = (lvl: number) => lvl + (st.from !== st.to ? 4 : 0) + (flicker ? 8 : 0);
556	      if (st.from === st.to) {
557	        if (visible) {
558	          this.emit(st, st.from, SOLID, 1, sh === st.from, debug(st.from));
559	          this.drawing.levels[st.from]++;
560	          drawn++;
561	        }
562	        if (sh >= 0 && (sh !== st.from || !visible)) this.emit(st, sh, SHADOW_ONLY, 1, true, 0);
563	      } else {
564	        if (visible) {
565	          this.emit(st, st.from, OUTGOING, st.fade, sh === st.from, debug(st.from));
566	          this.emit(st, st.to, INCOMING, st.fade, sh === st.to, debug(st.to));
567	          this.drawing.fading++;
568	          drawn++;
569	        }
570	        if (sh >= 0 && ((sh !== st.from && sh !== st.to) || !visible)) this.emit(st, sh, SHADOW_ONLY, 1, true, 0);
571	      }
572	    }
573	    for (const b of this.dynamic.values()) this.upload(b, b.count);
574	    for (const b of this.statics.values()) this.drawing.levels[b.level] += b.solid;
575	    this.drawn = drawn + [...this.statics.values()].reduce((n, b) => n + b.solid, 0);
576	    this.flickering = flickering;
577	  }
578	
579	  private changed(st: TreeState): void {
580	    st.changes.push(this.time);
581	    if (st.changes.length > 4) st.changes.shift();
582	  }
583	
584	  private emit(st: TreeState, level: number, role: number, fade: number, shadow: boolean, debug: number): void {
585	    const b = this.dynamicBatch(st.lv, level);
586	    const i = b.count++;
587	    if (b.count > b.capacity) this.ensureCapacity(b, b.count);
588	    b.mat.set(st.m, i * 16);
589	    b.inst.set(st.inst, i * 4);
590	    b.fade[i * 4] = fade;
591	    b.fade[i * 4 + 1] = role;
592	    b.fade[i * 4 + 2] = shadow ? 1 : 0;
593	    b.fade[i * 4 + 3] = debug;
594	  }
595	
596	  private dynamicBatch(lv: LoadedVariant, level: number): Batch {
597	    const key = `${lv.info.species}#${lv.info.index}:${level}`;
598	    let b = this.dynamic.get(key);
599	    if (!b) {
600	      b = this.newBatch();
601	      this.createMeshes(b, lv, level, `lod${level}`);
602	      this.ensureCapacity(b, 64);
603	      this.dynamic.set(key, b);
604	    }
605	    return b;
606	  }
607	
608	  private staticBatch(lv: LoadedVariant, level: number): StaticBatch {
609	    const key = `${lv.info.species}#${lv.info.index}:${level}`;
610	    let b = this.statics.get(key);
611	    if (!b) {
612	      const f = () => new Float32Array(0);
613	      b = {
614	        ...this.newBatch(),
615	        lv,
616	        level,
617	        sMat: f(),
618	        sInst: f(),
619	        sFade: f(),
620	        sAngle: f(),
621	        sAlways: f(),
622	        sCount: 0,
623	        cMat: f(),
624	        cInst: f(),
625	        cFade: f(),
626	        cAngle: f(),
627	        cAlways: f(),
628	        cCount: 0,
629	        solid: 0,
630	      };
631	      this.createMeshes(b, lv, level, `static lod${level}`);
632	      this.ensureCapacity(b, 64);
633	      this.statics.set(key, b);
634	    }
635	    return b;
636	  }
637	
638	  private newBatch(): Batch {
639	    return {
640	      meshes: [],
641	      geometries: [],
642	      capacity: 0,
643	      count: 0,
644	      mat: new Float32Array(0),
645	      inst: new Float32Array(0),
646	      fade: new Float32Array(0),
647	      aMat: null,
648	      aInst: null,
649	      aFade: null,
650	    };
651	  }
652	
653	  private setView(camera: PerspectiveCamera): void {
654	    const dir = camera.getWorldDirection(_dir);
655	    const flat = Math.hypot(dir.x, dir.z);
656	    const halfFov = Math.atan(Math.tan((camera.fov * Math.PI) / 360) * camera.aspect);
657	    this.view = flat > 0.4 ? { yaw: Math.atan2(dir.z, dir.x), half: halfFov + VIEW_MARGIN } : null;
658	    const v = this.view;
659	    const p = this.packedView;
660	    if (!v && !p) return;
661	    if (v && p) {
662	      let a = Math.abs(v.yaw - p.yaw) % (2 * Math.PI);
663	      if (a > Math.PI) a = 2 * Math.PI - a;
664	      if (a < REPACK && Math.abs(v.half - p.half) < REPACK) return;
665	    }
666	    this.packedView = v && { ...v };
667	    for (const b of this.statics.values()) this.packStatic(b);
668	  }
669	
670	  /** Static impostors -> GPU: the ones in the (repack) view window, solid, no shadow. */
671	  private packStatic(b: StaticBatch): void {
672	    const v = this.packedView ?? this.view;
673	    this.ensureCapacity(b, b.cCount);
674	    let n = 0;
675	    let solid = 0;
676	    for (let i = 0; i < b.cCount; i++) {
677	      if (v && !b.cAlways[i]) {
678	        let a = Math.abs(b.cAngle[i] - v.yaw) % (2 * Math.PI);
679	        if (a > Math.PI) a = 2 * Math.PI - a;
680	        if (a > v.half) continue;
681	      }
682	      b.mat.set(b.cMat.subarray(i * 16, i * 16 + 16), n * 16);
683	      b.inst.set(b.cInst.subarray(i * 4, i * 4 + 4), n * 4);
684	      b.fade.set(b.cFade.subarray(i * 4, i * 4 + 4), n * 4);
685	      if (b.cFade[i * 4 + 1] === SOLID) solid++;
686	      n++;
687	    }
688	    b.count = n;
689	    b.solid = solid;
690	    this.upload(b, n);
691	  }
692	
693	  private upload(b: Batch, n: number): void {
694	    for (const a of [b.aMat!, b.aInst!, b.aFade!]) {
695	      a.clearUpdateRanges();
696	      a.addUpdateRange(0, n * a.itemSize);
697	      a.needsUpdate = n > 0;
698	    }
699	    for (const mesh of b.meshes) {
700	      mesh.count = n;
701	      mesh.visible = n > 0;
702	    }
703	  }
704	
705	  /** CPU + GPU instance buffers for `n` instances (shared by the batch's meshes). */
706	  private ensureCapacity(b: Batch, n: number): void {
707	    if (n <= b.capacity) return;
708	    let cap = Math.max(64, b.capacity);
709	    while (cap < n) cap *= 2;
710	    const keep = Math.min(b.count, cap);
711	    const attr = (size: number, old: Float32Array) => {
712	      const arr = new Float32Array(cap * size);
713	      arr.set(old.subarray(0, keep * size));
714	      const a = new InstancedBufferAttribute(arr, size);
715	      a.setUsage(DynamicDrawUsage);
716	      return a;
717	    };
718	    b.aMat = attr(16, b.mat);
719	    b.aInst = attr(4, b.inst);
720	    b.aFade = attr(4, b.fade);
721	    b.mat = b.aMat.array as Float32Array;
722	    b.inst = b.aInst.array as Float32Array;
723	    b.fade = b.aFade.array as Float32Array;
724	    b.meshes.forEach((mesh, i) => {
725	      mesh.instanceMatrix = b.aMat!;
726	      const g = b.geometries[i];
727	      g.setAttribute('treeInst', b.aInst!);
728	      g.setAttribute('treeFade', b.aFade!);
729	    });
730	    b.capacity = cap;
731	  }
732	
733	  private createMeshes(b: Batch, lv: LoadedVariant, level: number, tag: string): void {
734	    const parts: { src: BufferGeometry; material: Material; leaf: boolean }[] =
735	      level < 3
736	        ? [
737	            { src: lv.levels[level].bark, material: barkMaterial(lv.def.bark.texture), leaf: false },
738	            { src: lv.levels[level].foliage, material: foliageMaterial(lv.def.foliage.kind), leaf: true },
739	          ]
740	        : [{ src: impostorQuad(), material: lv.impostor.material, leaf: false }];
741	    const casts = level === 1 || level === 2;
742	    for (const p of parts) {
743	      // A wrapper drawing the shared vertex buffers, carrying this batch's instance attributes.
744	      const g = new BufferGeometry();
745	      for (const [name, a] of Object.entries(p.src.attributes)) g.setAttribute(name, a);
746	      g.setIndex(p.src.index);
747	      g.boundingSphere = p.src.boundingSphere;
748	      const mesh = new InstancedMesh(g, p.material, 1);
749	      mesh.count = 0;
750	      mesh.visible = false;
751	      mesh.frustumCulled = false;
752	      mesh.castShadow = casts;
753	      mesh.receiveShadow = true;
754	      if (casts) mesh.customDepthMaterial = treeDepthMaterial(p.leaf);
755	      mesh.name = `tree ${lv.info.species}#${lv.info.index} ${tag}${p.leaf ? ' leaves' : ''}`;
756	      // Counters and GPU timing of exactly the tree draws (trees/Performance.md#counters).
757	      mesh.onBeforeRender = () => {
758	        this.drawing.mainDraws++;
759	        this.drawing.mainTriangles += meshTriangles(mesh);
760	        this.timer?.begin(false);
761	      };
762	      mesh.onAfterRender = () => this.timer?.end();
763	      mesh.onBeforeShadow = () => {
764	        this.drawing.shadowDraws++;
765	        this.drawing.shadowTriangles += meshTriangles(mesh);
766	        this.timer?.begin(true);
767	      };
768	      mesh.onAfterShadow = () => this.timer?.end();
769	      b.meshes.push(mesh);
770	      b.geometries.push(g);
771	      this.group.add(mesh);
772	    }
773	  }
774	
775	  /** Every batch made visible, so renderer.compile() builds all tree programs at load time. */
776	  prewarm(): void {
777	    for (const lv of this.library.all()) {
778	      for (let level = 0; level < 4; level++)
779	        for (const m of this.dynamicBatch(lv, level).meshes) m.visible = true;
780	      for (let level = 0; level < 4; level++)
781	        for (const m of this.staticBatch(lv, level).meshes) m.visible = true;
782	    }
783	  }
784	
785	  /** Re-apply visibility after prewarm / compile. */
786	  settle(): void {
787	    for (const b of [...this.dynamic.values(), ...this.statics.values()])
788	      for (const m of b.meshes) m.visible = m.count > 0;
789	  }
790	
791	  get busy(): boolean {
792	    return this.job !== null;
793	  }
794	
795	  get meshCount(): number {
796	    let n = 0;
797	    for (const b of [...this.dynamic.values(), ...this.statics.values()]) n += b.count > 0 ? b.meshes.length : 0;
798	    return n;
799	  }
800	
801	  dispose(): void {
802	    for (const b of [...this.dynamic.values(), ...this.statics.values()]) {
803	      // Free only this batch's instance buffers: the vertex buffers belong to the library (TreeLibrary.dispose).
804	      for (const g of b.geometries) {
805	        for (const name of Object.keys(g.attributes))
806	          if (name !== 'treeInst' && name !== 'treeFade') g.deleteAttribute(name);
807	        g.setIndex(null);
808	        g.dispose();
809	      }
810	      for (const m of b.meshes) m.dispose();
811	    }
812	    this.dynamic.clear();
813	    this.statics.clear();
814	    this.group.clear();
815	  }
816	}
