60	export interface Crown {
61	  c: V3;
62	  r: V3;
63	}
64	
65	export interface VariantMeshes {
66	  levels: [LevelMesh, LevelMesh, LevelMesh];
67	  crown: Crown;
68	  /** Top of the tree incl. foliage (m) and its widest horizontal reach. */
69	  height: number;
70	  radius: number;
71	  /** Bounding sphere centre height and radius (impostor frames). */
72	  sphere: { cy: number; r: number };
73	  /** Mean foliage colour (linear). */
74	  foliageColor: V3;
75	}
76	
77	/** Tube sides per branch order (last entry for every higher order). */
78	const SIDES: number[][] = [
79	  [8, 5, 4, 3],
80	  [6, 4, 3, 3],
81	  [5, 3],
82	];
83	/** Cluster cards overlap: share of their area that counts towards the merged / crown cards. */
84	const OVERLAP = 0.45;
85	/** Tiled cards fade to an ellipse (trees/materials.ts): this much larger, they cover the same area. */
86	const ELLIPSE = 1.13;
87	/** LOD2: leaf points per set of crown cards (a big limb gets a few sets). */
88	const CROWN_GROUP = 45;
89	
90	class Builder {
91	  p: number[] = [];
92	  n: number[] = [];
93	  uv: number[] = [];
94	  c: number[] = [];
95	  w: number[] = [];
96	  cu: number[] = [];
97	  idx: number[] = [];
98	
99	  get count(): number {
100	    return this.p.length / 3;
101	  }
102	
103	  vertex(
104	    p: V3,
105	    n: V3,
106	    u: number,
107	    v: number,
108	    c: V3,
109	    w: [number, number, number, number],
110	    card: [number, number] = [-1, -1],
111	  ): void {
112	    this.cu.push(card[0], card[1]);
113	    this.p.push(p[0], p[1], p[2]);
114	    this.n.push(n[0], n[1], n[2]);
115	    this.uv.push(u, v);
116	    this.c.push(c[0], c[1], c[2]);
117	    this.w.push(w[0], w[1], w[2], w[3]);
118	  }
119	
120	  build(): MeshData {
121	    return {
122	      position: new Float32Array(this.p),
123	      normal: new Float32Array(this.n),
124	      uv: new Float32Array(this.uv),
125	      color: new Float32Array(this.c),
126	      wind: new Float32Array(this.w),
127	      card: new Float32Array(this.cu),
128	      index: new Uint32Array(this.idx),
129	    };
130	  }
131	}
132	
133	const smoothstep = (a: number, b: number, x: number) => {
134	  const t = Math.min(1, Math.max(0, (x - a) / (b - a)));
135	  return t * t * (3 - 2 * t);
136	};
137	
138	function fitCrown(sk: Skeleton, card: number): Crown {
139	  const ls = sk.leaves;
140	  if (!ls.length) return { c: [0, sk.height * 0.6, 0], r: [1, 1, 1] };
141	  let c: V3 = [0, 0, 0];
142	  for (const l of ls) c = madd(c, l.pos, 1 / ls.length);
143	  let rxz = 0;
144	  let ry = 0;
145	  for (const l of ls) {
146	    const d = sub(l.pos, c);
147	    rxz = Math.max(rxz, Math.sqrt(d[0] * d[0] + d[2] * d[2]));
148	    ry = Math.max(ry, Math.abs(d[1]));
149	  }
150	  rxz = Math.max(0.3, rxz + card * 0.5);
151	  ry = Math.max(0.3, ry + card * 0.5);
152	  return { c, r: [rxz, ry, rxz] };
153	}
154	
155	/** Crown-relative position: ellipsoid "radius" (1 on its surface) and outward normal. */
156	function crownAt(cr: Crown, p: V3): { e: number; n: V3 } {
157	  const d: V3 = [(p[0] - cr.c[0]) / cr.r[0], (p[1] - cr.c[1]) / cr.r[1], (p[2] - cr.c[2]) / cr.r[2]];
158	  const e = len(d);
159	  return { e, n: norm([d[0] / cr.r[0], d[1] / cr.r[1], d[2] / cr.r[2]]) };
160	}
161	
162	/** Ambient occlusion from how deep a point sits inside the crown. */
163	function occlusion(cr: Crown, p: V3): number {
164	  return 0.35 + 0.65 * smoothstep(0.1, 1.0, crownAt(cr, p).e);
165	}
166	
167	/** Card normal blended with the crown's: the crown shades as one soft volume. */
168	function foliageNormal(cr: Crown, p: V3, card: V3): V3 {
169	  const ce = crownAt(cr, p).n;
170	  const s = card[0] * ce[0] + card[1] * ce[1] + card[2] * ce[2] < 0 ? -1 : 1;
171	  return norm(madd(scale(ce, 0.65), card, 0.35 * s));
172	}
173	
174	function perpendicular(d: V3): V3 {
175	  return norm(cross(d, Math.abs(d[1]) < 0.95 ? [0, 1, 0] : [1, 0, 0]));
176	}
177	
178	interface WindData {
179	  /** Phase of each segment's first-order limb (rad) and the distance along that limb at the segment start (m). */
180	  phase: Float32Array;
181	  dist: Float32Array;
182	}
183	
184	/**
185	 * Wind data per segment: every segment of a first-order limb (and its twigs) shares the limb's phase, and the
186	 * distance runs along the path from where the limb leaves the trunk, so a twig sways with the limb it grows on.
187	 */
188	function windData(sk: Skeleton, seed: number): WindData {
189	  const n = sk.segments.length;
190	  const phase = new Float32Array(n);
191	  const dist = new Float32Array(n);
192	  sk.segments.forEach((s, i) => {
193	    const p = s.parent >= 0 ? sk.segments[s.parent] : null;
194	    if (s.order === 0 || !p || p.order === 0) {
195	      phase[i] = unit(mix32(seed, s.branch + 1)) * Math.PI * 2;
196	      dist[i] = 0;
197	    } else {
198	      phase[i] = phase[s.parent];
199	      dist[i] = dist[s.parent] + len(sub(p.end, p.start));
200	    }
201	  });
202	  return { phase, dist };
203	}
204	
205	function leafWind(sk: Skeleton, wd: WindData, l: LeafPoint): [number, number] {
206	  if (l.segment < 0) return [0, 0];
207	  const s = sk.segments[l.segment];
208	  return [wd.phase[l.segment], wd.dist[l.segment] + len(sub(s.end, s.start))];
209	}
210	
211	function tube(
212	  b: Builder,
213	  sk: Skeleton,
214	  i: number,
215	  sides: number,
216	  bark: V3,
217	  tiling: number,
218	  cr: Crown,
219	  wd: WindData,
220	): void {
221	  const s = sk.segments[i];
222	  const d = segmentDir(s);
223	  const a = perpendicular(d);
224	  const c = cross(d, a);
225	  const length = len(sub(s.end, s.start));
226	  // Overlap into the next segment: no gap on the outside of a bend.
227	  const end = madd(s.end, d, Math.min(s.r1 * 0.6, length * 0.5));
228	  const base = b.count;
229	  for (let ring = 0; ring < 2; ring++) {
230	    const o = ring ? end : s.start;
231	    const r = ring ? s.r1 : s.r0;
232	    const v = (s.dist + (ring ? length : 0)) * tiling;
233	    const wd2 = wd.dist[i] + (ring ? length : 0);
234	    for (let k = 0; k <= sides; k++) {
235	      const t = (k / sides) * Math.PI * 2;
236	      const n = norm(madd(scale(a, tcos(t)), c, tsin(t)));
237	      const p = madd(o, n, r);
238	      const ao = occlusion(cr, p);
239	      b.vertex(p, n, k / sides, v, bark, [s.order, wd.phase[i], wd2, ao]);
240	    }
241	  }
242	  for (let k = 0; k < sides; k++) {
243	    const i0 = base + k;
244	    const i1 = base + sides + 1 + k;
245	    b.idx.push(i0, i1, i0 + 1, i0 + 1, i1, i1 + 1);
246	  }
247	}
248	
249	/** One quad: base centre `o`, along `d` for `length`, `half` to each side along `side`. */
250	function card(
251	  b: Builder,
252	  o: V3,
253	  d: V3,
254	  side: V3,
255	  length: number,
256	  half: number,
257	  tile: number,
258	  color: V3,
259	  w: [number, number],
260	  order: number,
261	  cr: Crown,
262	): void {
263	  const nrm = norm(cross(side, d));
264	  const base = b.count;
265	  for (const [su, sv] of [
266	    [0, 0],
267	    [1, 0],
268	    [1, 1],
269	    [0, 1],
270	  ]) {
271	    const p = madd(madd(o, side, (su * 2 - 1) * half), d, sv * length);
272	    // Cluster cards: u 0..0.5 of the atlas. Tiled cards: u >= 1, the dense leaf tile repeated every `tile` metres.
273	    const u = tile > 0 ? 1 + (su * 2 * half) / tile : su * 0.5;
274	    const v = tile > 0 ? (sv * length) / tile : sv;
275	    b.vertex(p, foliageNormal(cr, p, nrm), u, v, color, [
276	      order,
277	      w[0],
278	      w[1],
279	      occlusion(cr, p),
280	    ], tile > 0 ? [su, sv] : [-1, -1]);
281	  }
282	  b.idx.push(base, base + 1, base + 2, base, base + 2, base + 3);
283	}
284	
285	/** A leaf point's cluster: needle sprays along the twig, or broadleaf cards splayed from its tip. */
286	function cluster(
287	  b: Builder,
288	  sk: Skeleton,
289	  def: SpeciesDef,
290	  l: LeafPoint,
291	  color: V3,
292	  wd: WindData,
293	  cr: Crown,
294	): void {
295	  const f = def.foliage;
296	  const size = f.cardSize;
297	  const w = leafWind(sk, wd, l);
298	  const h = l.heading;
299	  // The cluster turns by the golden angle from its neighbour on the branch.
300	  const turn = l.index * GOLDEN;
301	  for (let j = 0; j < f.density; j++) {
302	    if (f.kind === 'needles') {
303	      const side = rotate(l.up, h, turn + (j * Math.PI) / f.density);
304	      card(b, madd(l.pos, h, -0.9 * size), h, side, size * 1.1, size * 0.35, 0, color, w, l.order, cr);
305	    } else {
306	      const around = rotate(l.up, h, turn + (j * Math.PI * 2) / f.density + j * GOLDEN * 0.25);
307	      const splay = 0.9;
308	      const d = norm(madd(scale(h, tcos(splay)), around, tsin(splay)));
309	      card(b, l.pos, d, norm(cross(d, around)), size, size * 0.5, 0, color, w, l.order, cr);
310	    }
311	  }
312	}
313	
314	function leafColor(def: SpeciesDef, seed: number, l: number): V3 {
315	  const rng = new TreeRng(mix32(seed ^ 0x51ed27, l));
316	  const pal = def.foliage.palette;
317	  const c = hexToLinear(pal[Math.floor(rng.next() * pal.length)]);
318	  return scale(c, rng.range(0.88, 1.1));
319	}
320	
321	function mean(cs: V3[]): V3 {
322	  let m: V3 = [0, 0, 0];
323	  for (const c of cs) m = madd(m, c, 1 / cs.length);
324	  return m;
325	}
326	
327	/** Big cards for a group of leaf points (LOD1 merged cards, LOD2 crown cards). */
328	function groupCards(
329	  b: Builder,
330	  attach: V3,
331	  ls: LeafPoint[],
332	  colors: V3[],
333	  def: SpeciesDef,
334	  w: [number, number],
335	  order: number,
336	  cr: Crown,
337	  crownCards: boolean,
338	): void {
339	  const size = def.foliage.cardSize;
340	  const color = mean(colors);
341	  const centroid = mean(ls.map((l) => l.pos));
342	  let d = sub(centroid, attach);
343	  if (len(d) < 1e-3) d = ls[0].heading;
344	  d = norm(d);
345	  const s1 = perpendicular(d);
346	  const s2 = norm(cross(d, s1));
347	  const area = ls.length * def.foliage.density * size * size * OVERLAP;
348	  if (!crownCards) {
349	    // From where the pruned subtree left the branch out past its farthest cluster: two crossed cards.
350	    let far = size;
351	    for (const l of ls) far = Math.max(far, len(sub(l.pos, attach)) + size * 0.5);
352	    const half = Math.min(far * 0.6, Math.max(size * 0.5, area / far / 4));
353	    card(b, attach, d, s1, far * ELLIPSE, half * ELLIPSE, size, color, w, order, cr);
354	    card(b, attach, d, s2, far * ELLIPSE, half * ELLIPSE, size, color, w, order, cr);
355	    return;
356	  }
357	  // Crown cards fitted to the limb's clusters: two crossed vertical cards and a horizontal one through the centroid.
358	  const flat = norm([d[0], 0, d[2]]);
359	  const across = norm(cross([0, 1, 0], flat));
360	  let ea = size;
361	  let eb = size;
362	  let ey = size;
363	  for (const l of ls) {
364	    const q = sub(l.pos, centroid);
365	    ea = Math.max(ea, Math.abs(q[0] * flat[0] + q[2] * flat[2]) + size * 0.5);
366	    eb = Math.max(eb, Math.abs(q[0] * across[0] + q[2] * across[2]) + size * 0.5);
367	    ey = Math.max(ey, Math.abs(q[1]) + size * 0.5);
368	  }
369	  const up: V3 = [0, 1, 0];
370	  const lift = (o: V3, dd: V3, e: number) => madd(o, dd, -e);
371	  [ea, eb, ey] = [ea * ELLIPSE, eb * ELLIPSE, ey * ELLIPSE];
372	  card(b, lift(centroid, up, ey), up, flat, ey * 2, ea, size, color, w, order, cr);
373	  card(b, lift(centroid, up, ey), up, across, ey * 2, eb, size, color, w, order, cr);
374	  card(b, lift(centroid, flat, ea), flat, across, ea * 2, eb, size, color, w, order, cr);
375	}
376	
377	/**
378	 * Split a limb's leaf points into groups of about `size` by position (a few k-means rounds, seeded with evenly
379	 * spaced points: deterministic), each fitted with its own crown cards.
380	 */
381	function clusterGroups(ids: number[], leaves: LeafPoint[], size: number): number[][] {
382	  const k = Math.max(1, Math.round(ids.length / size));
383	  if (k === 1) return [ids];
384	  let centres: V3[] = [...Array(k).keys()].map((j) => leaves[ids[Math.floor(((j + 0.5) * ids.length) / k)]].pos);
385	  let groups: number[][] = [];
386	  for (let round = 0; round < 6; round++) {
387	    groups = centres.map(() => []);
388	    for (const i of ids) {
389	      const p = leaves[i].pos;
390	      let best = 0;
391	      let bd = Infinity;
392	      centres.forEach((c, j) => {
393	        const d = sub(p, c);
394	        const dd = d[0] * d[0] + d[1] * d[1] + d[2] * d[2];
395	        if (dd < bd) [bd, best] = [dd, j];
396	      });
397	      groups[best].push(i);
398	    }
399	    groups = groups.filter((g) => g.length);
400	    centres = groups.map((g) => mean(g.map((i) => leaves[i].pos)));
401	  }
402	  return groups;
403	}
404	
405	/** Keep-mask of LOD1: prune the lowest priority segments until half remain (children always go first). */
406	export function pruneHalf(sk: Skeleton): Uint8Array {
407	  const n = sk.segments.length;
408	  const keep = new Uint8Array(n).fill(1);
409	  const order = [...Array(n).keys()].sort(
410	    (a, b) => sk.segments[a].priority - sk.segments[b].priority || b - a,
411	  );
412	  for (let k = 0; k < n - Math.ceil(n / 2); k++) keep[order[k]] = 0;
413	  return keep;
414	}
415	
416	export function buildMeshes(sk: Skeleton, def: SpeciesDef, seed: number): VariantMeshes {
417	  const size = def.foliage.cardSize;
418	  const cr = fitCrown(sk, size);
419	  const wd = windData(sk, seed);
420	  const bark = hexToLinear(def.bark.color);
421	  const tiling = def.bark.tiling;
422	  const colors = sk.leaves.map((_, i) => leafColor(def, seed, i));
423	  const n = sk.segments.length;
424	  const sides = (lod: number, order: number) => {
425	    const s = SIDES[lod];
426	    return s[Math.min(order, s.length - 1)];
427	  };
428	
429	  // LOD0
430	  const b0 = new Builder();
431	  for (let i = 0; i < n; i++) tube(b0, sk, i, sides(0, sk.segments[i].order), bark, tiling, cr, wd);
432	  const f0 = new Builder();
433	  sk.leaves.forEach((l, i) => cluster(f0, sk, def, l, colors[i], wd, cr));
434	
435	  // LOD1
436	  const keep1 = pruneHalf(sk);
437	  const b1 = new Builder();
438	  for (let i = 0; i < n; i++)
439	    if (keep1[i]) tube(b1, sk, i, sides(1, sk.segments[i].order), bark, tiling, cr, wd);
440	  const f1 = new Builder();
441	  const merged = new Map<number, number[]>();
442	  sk.leaves.forEach((l, li) => {
443	    // Leaf on a kept segment: its own cluster. Else: merged at the root of its pruned subtree.
444	    let root = -1;
445	    for (let s = l.segment; s >= 0 && !keep1[s]; s = sk.segments[s].parent) root = s;
446	    if (root < 0) cluster(f1, sk, def, l, colors[li], wd, cr);
447	    else {
448	      let g = merged.get(root);
449	      if (!g) merged.set(root, (g = []));
450	      g.push(li);
451	    }
452	  });
453	  for (const [root, group] of merged) {
454	    const s = sk.segments[root];
455	    groupCards(
456	      f1,
457	      s.start,
458	      group.map((i) => sk.leaves[i]),
459	      group.map((i) => colors[i]),
460	      def,
461	      [wd.phase[root], wd.dist[root]],
462	      s.order,
463	      cr,
464	      false,
465	    );
466	  }
467	
468	  // LOD2: trunk + first-order limbs (of LOD1: the levels nest), crown cards per limb.
469	  const b2 = new Builder();
470	  let segs2 = 0;
471	  for (let i = 0; i < n; i++)
472	    if (keep1[i] && sk.segments[i].order <= 1) {
473	      tube(b2, sk, i, sides(2, sk.segments[i].order), bark, tiling, cr, wd);
474	      segs2++;
475	    }
476	  const f2 = new Builder();
477	  const limbs = new Map<number, { attach: V3; seg: number; leaves: number[] }>();
478	  sk.leaves.forEach((l, li) => {
479	    let s = l.segment;
480	    while (s >= 0 && sk.segments[s].order > 1) s = sk.segments[s].parent;
481	    // Walk back to the limb's first segment (its attach point on the trunk).
482	    while (s >= 0) {
483	      const p = sk.segments[s].parent;
484	      if (p < 0 || sk.segments[p].branch !== sk.segments[s].branch) break;
485	      s = p;
486	    }
487	    const key = s < 0 ? -1 : sk.segments[s].branch;
488	    let g = limbs.get(key);
489	    if (!g)
490	      limbs.set(
491	        key,
492	        (g = { attach: s < 0 ? [0, 0, 0] : sk.segments[s].start, seg: s, leaves: [] }),
493	      );
494	    g.leaves.push(li);
495	  });
496	  for (const g of limbs.values())
497	    for (const part of clusterGroups(g.leaves, sk.leaves, CROWN_GROUP)) {
498	      const ls = part.map((i) => sk.leaves[i]);
499	      const centroid = mean(ls.map((l) => l.pos));
500	      const w: [number, number] =
501	        g.seg >= 0 ? [wd.phase[g.seg], wd.dist[g.seg] + len(sub(centroid, g.attach))] : [0, 0];
502	      groupCards(
503	        f2,
504	        g.attach,
505	        ls,
506	        part.map((i) => colors[i]),
507	        def,
508	        w,
509	        g.seg >= 0 ? sk.segments[g.seg].order : 0,
510	        cr,
511	        true,
512	      );
513	    }
514	
515	  // Bounds (LOD0 holds everything).
516	  let height = 0;
517	  let radius = 0;
518	  for (const m of [b0, f0])
519	    for (let i = 0; i < m.p.length; i += 3) {
520	      height = Math.max(height, m.p[i + 1]);
521	      radius = Math.max(radius, Math.sqrt(m.p[i] * m.p[i] + m.p[i + 2] * m.p[i + 2]));
522	    }
523	  const cy = height / 2;
524	  let r = 0;
525	  for (const m of [b0, f0, f1, f2])
526	    for (let i = 0; i < m.p.length; i += 3) {
527	      const dy = m.p[i + 1] - cy;
528	      r = Math.max(r, Math.sqrt(m.p[i] * m.p[i] + dy * dy + m.p[i + 2] * m.p[i + 2]));
529	    }
530	
531	  return {
532	    levels: [
533	      { bark: b0.build(), foliage: f0.build(), segments: n },
534	      { bark: b1.build(), foliage: f1.build(), segments: keep1.reduce((a, k) => a + k, 0) },
535	      { bark: b2.build(), foliage: f2.build(), segments: segs2 },
536	    ],
537	    crown: cr,
538	    height,
539	    radius,
540	    sphere: { cy, r: r * 1.02 },
541	    foliageColor: colors.length ? mean(colors) : hexToLinear(def.foliage.palette[0]),
542	  };
543	}
544	
545	/** Every typed array buffer of a variant's meshes (transferred from the worker, not copied). */
546	export function meshBuffers(m: VariantMeshes): ArrayBuffer[] {
547	  const out: ArrayBuffer[] = [];
548	  for (const l of m.levels)
549	    for (const d of [l.bark, l.foliage])
550	      for (const a of [d.position, d.normal, d.uv, d.color, d.wind, d.card, d.index])
551	        out.push(a.buffer as ArrayBuffer);
552	  return out;
553	}
