export interface Crown {
  c: V3;
  r: V3;
}

export interface VariantMeshes {
  levels: [LevelMesh, LevelMesh, LevelMesh];
  crown: Crown;
  /** Top of the tree incl. foliage (m) and its widest horizontal reach. */
  height: number;
  radius: number;
  /** Bounding sphere centre height and radius (impostor frames). */
  sphere: { cy: number; r: number };
  /** Mean foliage colour (linear). */
  foliageColor: V3;
}

/** Tube sides per branch order (last entry for every higher order). */
const SIDES: number[][] = [
  [8, 5, 4, 3],
  [6, 4, 3, 3],
  [5, 3],
];
/** Cluster cards overlap: share of their area that counts towards the merged / crown cards. */
const OVERLAP = 0.45;
/** Tiled cards fade to an ellipse (trees/materials.ts): this much larger, they cover the same area. */
const ELLIPSE = 1.13;
/** LOD2: leaf points per set of crown cards (a big limb gets a few sets). */
const CROWN_GROUP = 45;

class Builder {
  p: number[] = [];
  n: number[] = [];
  uv: number[] = [];
  c: number[] = [];
  w: number[] = [];
  cu: number[] = [];
  idx: number[] = [];

  get count(): number {
    return this.p.length / 3;
  }

  vertex(
    p: V3,
    n: V3,
    u: number,
    v: number,
    c: V3,
    w: [number, number, number, number],
    card: [number, number] = [-1, -1],
  ): void {
    this.cu.push(card[0], card[1]);
    this.p.push(p[0], p[1], p[2]);
    this.n.push(n[0], n[1], n[2]);
    this.uv.push(u, v);
    this.c.push(c[0], c[1], c[2]);
    this.w.push(w[0], w[1], w[2], w[3]);
  }

  build(): MeshData {
    return {
      position: new Float32Array(this.p),
      normal: new Float32Array(this.n),
      uv: new Float32Array(this.uv),
      color: new Float32Array(this.c),
      wind: new Float32Array(this.w),
      card: new Float32Array(this.cu),
      index: new Uint32Array(this.idx),
    };
  }
}

const smoothstep = (a: number, b: number, x: number) => {
  const t = Math.min(1, Math.max(0, (x - a) / (b - a)));
  return t * t * (3 - 2 * t);
};

function fitCrown(sk: Skeleton, card: number): Crown {
  const ls = sk.leaves;
  if (!ls.length) return { c: [0, sk.height * 0.6, 0], r: [1, 1, 1] };
  let c: V3 = [0, 0, 0];
  for (const l of ls) c = madd(c, l.pos, 1 / ls.length);
  let rxz = 0;
  let ry = 0;
  for (const l of ls) {
    const d = sub(l.pos, c);
    rxz = Math.max(rxz, Math.sqrt(d[0] * d[0] + d[2] * d[2]));
    ry = Math.max(ry, Math.abs(d[1]));
  }
  rxz = Math.max(0.3, rxz + card * 0.5);
  ry = Math.max(0.3, ry + card * 0.5);
  return { c, r: [rxz, ry, rxz] };
}

/** Crown-relative position: ellipsoid "radius" (1 on its surface) and outward normal. */
function crownAt(cr: Crown, p: V3): { e: number; n: V3 } {
  const d: V3 = [(p[0] - cr.c[0]) / cr.r[0], (p[1] - cr.c[1]) / cr.r[1], (p[2] - cr.c[2]) / cr.r[2]];
  const e = len(d);
  return { e, n: norm([d[0] / cr.r[0], d[1] / cr.r[1], d[2] / cr.r[2]]) };
}

/** Ambient occlusion from how deep a point sits inside the crown. */
function occlusion(cr: Crown, p: V3): number {
  return 0.35 + 0.65 * smoothstep(0.1, 1.0, crownAt(cr, p).e);
}

/** Card normal blended with the crown's: the crown shades as one soft volume. */
function foliageNormal(cr: Crown, p: V3, card: V3): V3 {
  const ce = crownAt(cr, p).n;
  const s = card[0] * ce[0] + card[1] * ce[1] + card[2] * ce[2] < 0 ? -1 : 1;
  return norm(madd(scale(ce, 0.65), card, 0.35 * s));
}

function perpendicular(d: V3): V3 {
  return norm(cross(d, Math.abs(d[1]) < 0.95 ? [0, 1, 0] : [1, 0, 0]));
}

interface WindData {
  /** Phase of each segment's first-order limb (rad) and the distance along that limb at the segment start (m). */
  phase: Float32Array;
  dist: Float32Array;
}

/**
 * Wind data per segment: every segment of a first-order limb (and its twigs) shares the limb's phase, and the
 * distance runs along the path from where the limb leaves the trunk, so a twig sways with the limb it grows on.
 */
function windData(sk: Skeleton, seed: number): WindData {
  const n = sk.segments.length;
  const phase = new Float32Array(n);
  const dist = new Float32Array(n);
  sk.segments.forEach((s, i) => {
    const p = s.parent >= 0 ? sk.segments[s.parent] : null;
    if (s.order === 0 || !p || p.order === 0) {
      phase[i] = unit(mix32(seed, s.branch + 1)) * Math.PI * 2;
      dist[i] = 0;
    } else {
      phase[i] = phase[s.parent];
      dist[i] = dist[s.parent] + len(sub(p.end, p.start));
    }
  });
  return { phase, dist };
}

function leafWind(sk: Skeleton, wd: WindData, l: LeafPoint): [number, number] {
  if (l.segment < 0) return [0, 0];
  const s = sk.segments[l.segment];
  return [wd.phase[l.segment], wd.dist[l.segment] + len(sub(s.end, s.start))];
}

function tube(
  b: Builder,
  sk: Skeleton,
  i: number,
  sides: number,
  bark: V3,
  tiling: number,
  cr: Crown,
  wd: WindData,
): void {
  const s = sk.segments[i];
  const d = segmentDir(s);
  const a = perpendicular(d);
  const c = cross(d, a);
  const length = len(sub(s.end, s.start));
  // Overlap into the next segment: no gap on the outside of a bend.
  const end = madd(s.end, d, Math.min(s.r1 * 0.6, length * 0.5));
  const base = b.count;
  for (let ring = 0; ring < 2; ring++) {
    const o = ring ? end : s.start;
    const r = ring ? s.r1 : s.r0;
    const v = (s.dist + (ring ? length : 0)) * tiling;
    const wd2 = wd.dist[i] + (ring ? length : 0);
    for (let k = 0; k <= sides; k++) {
      const t = (k / sides) * Math.PI * 2;
      const n = norm(madd(scale(a, tcos(t)), c, tsin(t)));
      const p = madd(o, n, r);
      const ao = occlusion(cr, p);
      b.vertex(p, n, k / sides, v, bark, [s.order, wd.phase[i], wd2, ao]);
    }
  }
  for (let k = 0; k < sides; k++) {
    const i0 = base + k;
    const i1 = base + sides + 1 + k;
    b.idx.push(i0, i1, i0 + 1, i0 + 1, i1, i1 + 1);
  }
}

/** One quad: base centre `o`, along `d` for `length`, `half` to each side along `side`. */
function card(
  b: Builder,
  o: V3,
  d: V3,
  side: V3,
  length: number,
  half: number,
  tile: number,
  color: V3,
  w: [number, number],
  order: number,
  cr: Crown,
): void {
  const nrm = norm(cross(side, d));
  const base = b.count;
  for (const [su, sv] of [
    [0, 0],
    [1, 0],
    [1, 1],
    [0, 1],
  ]) {
    const p = madd(madd(o, side, (su * 2 - 1) * half), d, sv * length);
    // Cluster cards: u 0..0.5 of the atlas. Tiled cards: u >= 1, the dense leaf tile repeated every `tile` metres.
    const u = tile > 0 ? 1 + (su * 2 * half) / tile : su * 0.5;
    const v = tile > 0 ? (sv * length) / tile : sv;
    b.vertex(p, foliageNormal(cr, p, nrm), u, v, color, [
      order,
      w[0],
      w[1],
      occlusion(cr, p),
    ], tile > 0 ? [su, sv] : [-1, -1]);
  }
  b.idx.push(base, base + 1, base + 2, base, base + 2, base + 3);
}

/** A leaf point's cluster: needle sprays along the twig, or broadleaf cards splayed from its tip. */
function cluster(
  b: Builder,
  sk: Skeleton,
  def: SpeciesDef,
  l: LeafPoint,
  color: V3,
  wd: WindData,
  cr: Crown,
): void {
  const f = def.foliage;
  const size = f.cardSize;
  const w = leafWind(sk, wd, l);
  const h = l.heading;
  // The cluster turns by the golden angle from its neighbour on the branch.
  const turn = l.index * GOLDEN;
  for (let j = 0; j < f.density; j++) {
    if (f.kind === 'needles') {
      const side = rotate(l.up, h, turn + (j * Math.PI) / f.density);
      card(b, madd(l.pos, h, -0.9 * size), h, side, size * 1.1, size * 0.35, 0, color, w, l.order, cr);
    } else {
      const around = rotate(l.up, h, turn + (j * Math.PI * 2) / f.density + j * GOLDEN * 0.25);
      const splay = 0.9;
      const d = norm(madd(scale(h, tcos(splay)), around, tsin(splay)));
      card(b, l.pos, d, norm(cross(d, around)), size, size * 0.5, 0, color, w, l.order, cr);
    }
  }
}

function leafColor(def: SpeciesDef, seed: number, l: number): V3 {
  const rng = new TreeRng(mix32(seed ^ 0x51ed27, l));
  const pal = def.foliage.palette;
  const c = hexToLinear(pal[Math.floor(rng.next() * pal.length)]);
  return scale(c, rng.range(0.88, 1.1));
}

function mean(cs: V3[]): V3 {
  let m: V3 = [0, 0, 0];
  for (const c of cs) m = madd(m, c, 1 / cs.length);
  return m;
}

/** Big cards for a group of leaf points (LOD1 merged cards, LOD2 crown cards). */
function groupCards(
  b: Builder,
  attach: V3,
  ls: LeafPoint[],
  colors: V3[],
  def: SpeciesDef,
  w: [number, number],
  order: number,
  cr: Crown,
  crownCards: boolean,
): void {
  const size = def.foliage.cardSize;
  const color = mean(colors);
  const centroid = mean(ls.map((l) => l.pos));
  let d = sub(centroid, attach);
  if (len(d) < 1e-3) d = ls[0].heading;
  d = norm(d);
  const s1 = perpendicular(d);
  const s2 = norm(cross(d, s1));
  const area = ls.length * def.foliage.density * size * size * OVERLAP;
  if (!crownCards) {
    // From where the pruned subtree left the branch out past its farthest cluster: two crossed cards.
    let far = size;
    for (const l of ls) far = Math.max(far, len(sub(l.pos, attach)) + size * 0.5);
    const half = Math.min(far * 0.6, Math.max(size * 0.5, area / far / 4));
    card(b, attach, d, s1, far * ELLIPSE, half * ELLIPSE, size, color, w, order, cr);
    card(b, attach, d, s2, far * ELLIPSE, half * ELLIPSE, size, color, w, order, cr);
    return;
  }
  // Crown cards fitted to the limb's clusters: two crossed vertical cards and a horizontal one through the centroid.
  const flat = norm([d[0], 0, d[2]]);
  const across = norm(cross([0, 1, 0], flat));
  let ea = size;
  let eb = size;
  let ey = size;
  for (const l of ls) {
    const q = sub(l.pos, centroid);
    ea = Math.max(ea, Math.abs(q[0] * flat[0] + q[2] * flat[2]) + size * 0.5);
    eb = Math.max(eb, Math.abs(q[0] * across[0] + q[2] * across[2]) + size * 0.5);
    ey = Math.max(ey, Math.abs(q[1]) + size * 0.5);
  }
  const up: V3 = [0, 1, 0];
  const lift = (o: V3, dd: V3, e: number) => madd(o, dd, -e);
  [ea, eb, ey] = [ea * ELLIPSE, eb * ELLIPSE, ey * ELLIPSE];
  card(b, lift(centroid, up, ey), up, flat, ey * 2, ea, size, color, w, order, cr);
  card(b, lift(centroid, up, ey), up, across, ey * 2, eb, size, color, w, order, cr);
  card(b, lift(centroid, flat, ea), flat, across, ea * 2, eb, size, color, w, order, cr);
}

/**
 * Split a limb's leaf points into groups of about `size` by position (a few k-means rounds, seeded with evenly
 * spaced points: deterministic), each fitted with its own crown cards.
 */
function clusterGroups(ids: number[], leaves: LeafPoint[], size: number): number[][] {
  const k = Math.max(1, Math.round(ids.length / size));
  if (k === 1) return [ids];
  let centres: V3[] = [...Array(k).keys()].map((j) => leaves[ids[Math.floor(((j + 0.5) * ids.length) / k)]].pos);
  let groups: number[][] = [];
  for (let round = 0; round < 6; round++) {
    groups = centres.map(() => []);
    for (const i of ids) {
      const p = leaves[i].pos;
      let best = 0;
      let bd = Infinity;
      centres.forEach((c, j) => {
        const d = sub(p, c);
        const dd = d[0] * d[0] + d[1] * d[1] + d[2] * d[2];
        if (dd < bd) [bd, best] = [dd, j];
      });
      groups[best].push(i);
    }
    groups = groups.filter((g) => g.length);
    centres = groups.map((g) => mean(g.map((i) => leaves[i].pos)));
  }
  return groups;
}

/** Keep-mask of LOD1: prune the lowest priority segments until half remain (children always go first). */
export function pruneHalf(sk: Skeleton): Uint8Array {
  const n = sk.segments.length;
  const keep = new Uint8Array(n).fill(1);
  const order = [...Array(n).keys()].sort(
    (a, b) => sk.segments[a].priority - sk.segments[b].priority || b - a,
  );
  for (let k = 0; k < n - Math.ceil(n / 2); k++) keep[order[k]] = 0;
  return keep;
}

export function buildMeshes(sk: Skeleton, def: SpeciesDef, seed: number): VariantMeshes {
  const size = def.foliage.cardSize;
  const cr = fitCrown(sk, size);
  const wd = windData(sk, seed);
  const bark = hexToLinear(def.bark.color);
  const tiling = def.bark.tiling;
  const colors = sk.leaves.map((_, i) => leafColor(def, seed, i));
  const n = sk.segments.length;
  const sides = (lod: number, order: number) => {
    const s = SIDES[lod];
    return s[Math.min(order, s.length - 1)];
  };

  // LOD0
  const b0 = new Builder();
  for (let i = 0; i < n; i++) tube(b0, sk, i, sides(0, sk.segments[i].order), bark, tiling, cr, wd);
  const f0 = new Builder();
  sk.leaves.forEach((l, i) => cluster(f0, sk, def, l, colors[i], wd, cr));

  // LOD1
  const keep1 = pruneHalf(sk);
  const b1 = new Builder();
  for (let i = 0; i < n; i++)
    if (keep1[i]) tube(b1, sk, i, sides(1, sk.segments[i].order), bark, tiling, cr, wd);
  const f1 = new Builder();
  const merged = new Map<number, number[]>();
  sk.leaves.forEach((l, li) => {
    // Leaf on a kept segment: its own cluster. Else: merged at the root of its pruned subtree.
    let root = -1;
    for (let s = l.segment; s >= 0 && !keep1[s]; s = sk.segments[s].parent) root = s;
    if (root < 0) cluster(f1, sk, def, l, colors[li], wd, cr);
    else {
      let g = merged.get(root);
      if (!g) merged.set(root, (g = []));
      g.push(li);
    }
  });
  for (const [root, group] of merged) {
    const s = sk.segments[root];
    groupCards(
      f1,
      s.start,
      group.map((i) => sk.leaves[i]),
      group.map((i) => colors[i]),
      def,
      [wd.phase[root], wd.dist[root]],
      s.order,
      cr,
      false,
    );
  }

  // LOD2: trunk + first-order limbs (of LOD1: the levels nest), crown cards per limb.
  const b2 = new Builder();
  let segs2 = 0;
  for (let i = 0; i < n; i++)
    if (keep1[i] && sk.segments[i].order <= 1) {
      tube(b2, sk, i, sides(2, sk.segments[i].order), bark, tiling, cr, wd);
      segs2++;
    }
  const f2 = new Builder();
  const limbs = new Map<number, { attach: V3; seg: number; leaves: number[] }>();
  sk.leaves.forEach((l, li) => {
    let s = l.segment;
    while (s >= 0 && sk.segments[s].order > 1) s = sk.segments[s].parent;
    // Walk back to the limb's first segment (its attach point on the trunk).
    while (s >= 0) {
      const p = sk.segments[s].parent;
      if (p < 0 || sk.segments[p].branch !== sk.segments[s].branch) break;
      s = p;
    }
    const key = s < 0 ? -1 : sk.segments[s].branch;
    let g = limbs.get(key);
    if (!g)
      limbs.set(
        key,
        (g = { attach: s < 0 ? [0, 0, 0] : sk.segments[s].start, seg: s, leaves: [] }),
      );
    g.leaves.push(li);
  });
  for (const g of limbs.values())
    for (const part of clusterGroups(g.leaves, sk.leaves, CROWN_GROUP)) {
      const ls = part.map((i) => sk.leaves[i]);
      const centroid = mean(ls.map((l) => l.pos));
      const w: [number, number] =
        g.seg >= 0 ? [wd.phase[g.seg], wd.dist[g.seg] + len(sub(centroid, g.attach))] : [0, 0];
      groupCards(
        f2,
        g.attach,
        ls,
        part.map((i) => colors[i]),
        def,
        w,
        g.seg >= 0 ? sk.segments[g.seg].order : 0,
        cr,
        true,
      );
    }

  // Bounds (LOD0 holds everything).
  let height = 0;
  let radius = 0;
  for (const m of [b0, f0])
    for (let i = 0; i < m.p.length; i += 3) {
      height = Math.max(height, m.p[i + 1]);
      radius = Math.max(radius, Math.sqrt(m.p[i] * m.p[i] + m.p[i + 2] * m.p[i + 2]));
    }
  const cy = height / 2;
  let r = 0;
  for (const m of [b0, f0, f1, f2])
    for (let i = 0; i < m.p.length; i += 3) {
      const dy = m.p[i + 1] - cy;
      r = Math.max(r, Math.sqrt(m.p[i] * m.p[i] + dy * dy + m.p[i + 2] * m.p[i + 2]));
    }

  return {
    levels: [
      { bark: b0.build(), foliage: f0.build(), segments: n },
      { bark: b1.build(), foliage: f1.build(), segments: keep1.reduce((a, k) => a + k, 0) },
      { bark: b2.build(), foliage: f2.build(), segments: segs2 },
    ],
    crown: cr,
    height,
    radius,
    sphere: { cy, r: r * 1.02 },
    foliageColor: colors.length ? mean(colors) : hexToLinear(def.foliage.palette[0]),
  };
}

/** Every typed array buffer of a variant's meshes (transferred from the worker, not copied). */
export function meshBuffers(m: VariantMeshes): ArrayBuffer[] {
  const out: ArrayBuffer[] = [];
  for (const l of m.levels)
    for (const d of [l.bark, l.foliage])
      for (const a of [d.position, d.normal, d.uv, d.color, d.wind, d.card, d.index])
        out.push(a.buffer as ArrayBuffer);
  return out;
}

