export function foliageMaterial(kind: FoliageKind, pass: 'shade' | 'equal' = 'shade'): MeshStandardMaterial {
  const key = `leaf:${pass}:${kind}`;
  let m = materials.get(key) as MeshStandardMaterial | undefined;
  if (m) return m;
  m = new MeshStandardMaterial({
    vertexColors: true,
    map: foliageTexture(kind),
    alphaTest: ALPHA_TEST,
    side: DoubleSide,
    roughness: 0.85,
  });
  m.name = `tree ${key}`;
  m.alphaToCoverage = foliageA2C;
  m.defines = { TREE_LEAF: 1, RALLY_FOLIAGE: 0.45, TREE_AMBIENT: FOLIAGE_AMBIENT.toFixed(2) };
  if (pass === 'equal') {
