/** Check a with / without trees pair against the budget (a run over it is a failing result). */
export function checkBudget(runs: BenchRun[], treeLoadMs: number): BudgetResult {
  const failures: string[] = [];
  const on = runs.find((r) => r.trees);
  const off = runs.find((r) => !r.trees);
  if (on && off) {
    const avg = on.avgMs - off.avgMs;
    const low = on.low1Ms - off.low1Ms;
    if (avg > TREE_BUDGET.frameMs) failures.push(`frame time +${avg.toFixed(2)} ms > ${TREE_BUDGET.frameMs} ms`);
    if (low > TREE_BUDGET.low1Ms) failures.push(`1% low +${low.toFixed(2)} ms > ${TREE_BUDGET.low1Ms} ms`);
  } else failures.push('no run without trees to compare with');
  if (on && on.selectMs > TREE_BUDGET.selectMs)
    failures.push(`selection ${on.selectMs.toFixed(3)} ms > ${TREE_BUDGET.selectMs} ms`);
  if (treeLoadMs > TREE_BUDGET.loadMs) failures.push(`tree load ${Math.round(treeLoadMs)} ms > ${TREE_BUDGET.loadMs} ms`);
  return { pass: failures.length === 0, failures, budget: TREE_BUDGET };
